'use strict';
const R=window.RapDemRules;
let importValidated=false,dialogCallback=null,lastFocus=null;
const formData=selector=>Object.fromEntries(new FormData($(selector)));
function modal(title,body,actionLabel='Đã hiểu',callback=null){lastFocus=document.activeElement;dialogCallback=callback;$('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${E(title)}</h2>${btn('×','close-dialog','quiet','aria-label="Đóng hộp thoại"')}</div><div class="dialog-body">${body}</div><div class="dialog-foot">${btn('Hủy','close-dialog')}${btn(actionLabel,'dialog-confirm','primary')}</div>`;$('#dialog').showModal();}
function closeDialog(){ $('#dialog').close();dialogCallback=null;lastFocus?.focus(); }
function askReason(title,callback){modal(title,field('Lý do bắt buộc','reason','','text',true,'Chỉ ghi dữ liệu mô phỏng.'),'Xác nhận mẫu',()=>{const reason=$('#dialog [name=reason]').value.trim();if(!reason){$('#dialog [data-error=reason]').textContent='Vui lòng ghi lý do.';return false;}callback(reason);});}
function audit(action,detail){db.audit.unshift({action,detail,time:'Vừa thao tác'});}
function go(to){dirty=false;viewState='normal';if(route()===to)render();else location.hash=to;}
function allow(roles){if(!roles.includes(role)){showToast('Vai trò này không được thực hiện thao tác mẫu.',true);return false;}return true;}
function info(title,body){modal(title,`<p>${E(body)}</p><p class="muted small">Đây là màn thiết kế. Không có request backend hoặc thay đổi hệ thống thật.</p>`);}
function simpleScreen(title,subtitle,headers,rows,actions=''){return head(title,subtitle,actions)+`<section class="panel">${table(headers,rows)}</section>`;}
function tasks(){return simpleScreen('Công việc của tôi','Lọc theo người được phân công trong sản phẩm thật.',['Công việc','Nội dung','Trạng thái',''],db.tasks.map(t=>[t.title,t.subtitle,badge(t.status||'new'),link('Mở hồ sơ →',t.route,'help-link')]));}
function taxonomies(){return simpleScreen('Danh mục dùng chung','Không tách thể loại mobile với desktop.',['Thể loại','Slug','Trạng thái',''],['Hành động','Chính kịch','Viễn tưởng','Tâm lý','Kinh dị'].map((x,i)=>[x,['hanh-dong','chinh-kich','vien-tuong','tam-ly','kinh-di'][i],badge('active'),btn('Xem form','generic-form','quiet',`data-kind="Danh mục ${x}"`)]),btn('+ Thêm danh mục','generic-form','primary','data-kind="Danh mục mới"'));}
function assets(){return head('Thư viện ảnh','Không chứa video phim. Ảnh hiện tại là khối giữ chỗ có nhãn MẪU.',btn('Xem form tải ảnh','asset-picker','primary'))+`<div class="asset-grid">${db.movies.slice(0,8).map(m=>`<div class="asset-card"><div class="asset-thumb">ẢNH GIỮ CHỖ</div><div class="caption"><strong>${E(m.title)}</strong><p class="muted small">Chưa có asset production</p>${badge('pending')}</div></div>`).join('')}</div>`+callout('Upload thật cần kiểm tra','Kiểm MIME/chữ ký file, kích thước, scan; evidence và CSV lưu riêng tư. Không nhận HTML/SVG/JS tùy ý.','blue');}
function episodes(){return head('Tập phim nội bộ','Không thêm bộ chọn tập ngoài website khi chưa được duyệt.')+callout('Chưa mở luồng phim bộ','Chỉ xuất bản phim bộ khi đã xác minh người xem có thể chuyển đến mọi tập bằng trình phát đối tác. Nếu không hỗ trợ, cần chủ sản phẩm chốt luồng mới.')+panel('Cấu trúc dữ liệu',table(['Khóa duy nhất','Thông tin','Điều kiện'],[['movieId + season + number','Tên tập, nguồn phát, trạng thái','Phim phải có type=series'],['Nguồn từng tập','sourceId / providerId','Cùng phim và tập, có quyền phát']]))+btn('Xem form nội bộ','generic-form','','data-kind="Tập phim"');}
function sections(){return simpleScreen('Section trang chủ','Đề xuất 6 section; giá trị giới hạn cần chốt trước production.',['Thứ tự','Section','Nguồn','Trạng thái'],['Mới cập nhật','Đang được quan tâm','Phim lẻ nổi bật','Phim bộ','Hành động','Phim tâm lý'].map((t,i)=>[i+1,t,i<3?'Chọn thủ công':'Theo quy tắc',badge('draft')]),link('← Cấu hình chung','site','help-link'))+callout('Không tự bật nội dung chưa khả dụng','Phim bộ cần gate chuyển tập. Góc điện ảnh là nội dung P1; MVP chỉ banner tĩnh đã duyệt nếu có. Quảng cáo dùng slot riêng.','blue');}
function pages(){return simpleScreen('Trang thông tin','Nội dung nháp được duyệt trước khi công khai.',['Trang','Slug','Trạng thái',''],['Giới thiệu','Liên hệ','Điều khoản','Quyền riêng tư','Bản quyền'].map((n,i)=>[n,['gioi-thieu','lien-he','dieu-khoan','quyen-rieng-tu','ban-quyen'][i],badge('draft'),btn('Xem form','generic-form','quiet',`data-kind="${n}"`)]));}
function creatives(){return simpleScreen('Mẫu quảng cáo','Phê duyệt nội dung, đích liên kết và kích thước trước phân phối.',['Creative','Chiến dịch','Kích thước mẫu','Trạng thái',''],db.campaigns.map((c,i)=>['creative-'+(i+1),c.name,'728 × 90 CSS px',badge('approved'),btn('Xem cấu hình','creative-form','quiet')]),btn('+ Thêm mẫu','creative-form','primary'))+callout('Phê duyệt mẫu chỉ là trạng thái demo','Không chứa quảng cáo, hợp đồng hoặc đích click thật.');}
function payments(){return simpleScreen('Tiền thực nhận','Ghi nhận giao dịch, không thực hiện chuyển tiền.',['Tham chiếu mẫu','Đối tác','Tiền nhận','Phân bổ','Trạng thái'],[['BANK-DEMO-001','Đối tác minh họa','5.000.000 VND','5.000.000 VND / kỳ mẫu',badge('confirmed')]],btn('Xem form ghi nhận','payment-form','primary'))+callout('Tách công nợ và tiền nhận','Kỳ mẫu net 11.500.000 VND; nhận 5.000.000 VND; còn 6.500.000 VND. Đây không phải doanh thu thực.','blue');}
function auditScreen(){return head('Nhật ký kiểm toán','Append-only trong triển khai thật. Che mật khẩu, token và dữ liệu nhạy cảm.')+panel('Hoạt động phiên mẫu',table(['Hành động','Chi tiết','Thời gian'],db.audit.map(a=>[E(a.action),E(a.detail),a.time])));}
function jobs(){return head('Tác vụ hệ thống','Đã nhận tác vụ chưa có nghĩa là đã hoàn tất.')+tabs([['Hàng đợi','jobs'],['Cài đặt','settings'],['Sao lưu','backups'],['Nhật ký','audit']],'jobs')+panel('Hàng đợi minh họa',table(['Tác vụ','Đối tượng','Lần thử','Trạng thái',''],[['job-demo-001','publish / bản mẫu',1,badge(db.jobState||'failed'),btn('Thử lại mẫu','retry-job','quiet')],['job-demo-002','image / ảnh mẫu',1,badge('succeeded'),'—']]))+callout('Retry an toàn','Không tạo release / import trùng; lỗi vượt giới hạn chuyển dead-letter. Không log URL có token.','blue');}
function settings(){return head('Cài đặt hệ thống','Các giá trị dưới đây là đề xuất chưa duyệt.')+tabs([['Hàng đợi','jobs'],['Cài đặt','settings'],['Sao lưu','backups'],['Nhật ký','audit']],'settings')+panel('Thông số vận hành',detail([['Múi giờ hiển thị','Asia/Bangkok (UTC+7)'],['API / lưu trữ thời gian','UTC, RFC3339'],['Phiên nhân sự','Đề xuất 30 phút idle / 12 giờ tuyệt đối'],['Retry worker','Đề xuất 3 lần, có backoff'],['MFA','Bắt buộc quyền nhạy cảm'],['Secret','Secret manager, không trả plaintext']]))+callout('Chốt trước triển khai','Auth provider, domain, hosting, retention, ngưỡng cảnh báo và RPO/RTO chưa có xác nhận.');}
function backups(){return head('Sao lưu & khôi phục','Không có bản sao lưu thật trong prototype.',btn('Xem quy trình khôi phục','restore-info','danger'))+panel('Trạng thái thiết kế',table(['Hạng mục','Mục tiêu đề xuất','Bằng chứng hiện tại'],[['DB + cấu hình','Hằng ngày; RPO ≤24h','Chưa có'],['Khôi phục staging','Diễn tập theo lịch; RTO ≤4h','Chưa chạy'],['Production restore','Approval + step-up + backup trước restore','Không thực hiện từ prototype']]))+callout('File backup không chứng minh khả năng phục hồi','Phải phục hồi thử trên môi trường cô lập và kiểm tra quan hệ dữ liệu / quyền / cấu hình.');}
function components(){return head('Thành phần & danh sách màn','Bản HTML là nguồn của các ảnh xuất; ảnh không thay thế tài nguyên chữ thật.')+panel('Nền tảng giao diện',`<div class="grid three"><div class="swatch" style="background:#151b25;color:white">Sidebar #151B25</div><div class="swatch" style="background:#f3c459">Accent #F3C459</div><div class="swatch" style="background:#f4f5f7">Canvas #F4F5F7</div></div><p style="margin-top:16px">Segoe UI / Arial · body 14px · H1 28px · bảng cuộn trong khung.</p><div class="actions">${btn('Thử hộp xác nhận','generic-form','','data-kind="Hộp thoại mẫu"')}${link('Các trạng thái','states','help-link')}</div>`)+panel('Màn hình CMS V2',table(['ID','Màn hình','Phạm vi tương tác'],window.RAPDEM_SCREENS.map(s=>[s.id,link(s.title,s.route,'help-link'),s.coverage])));}
function states(){return head('Thư viện trạng thái','Chọn trạng thái ở thanh vàng để kiểm tra ở từng viewport.')+`<div class="grid equal">${panel('Rỗng',`<p>Chưa có dữ liệu / không có kết quả tìm kiếm.</p>${btn('Xem rỗng','state-empty')}`)}${panel('Lỗi',`<p>Không chuyển lỗi kết nối thành dữ liệu bằng 0.</p>${btn('Xem lỗi','state-error')}`)}${panel('Đang tải',`<div class="skeleton row"></div>${btn('Xem loading','state-loading')}`)}${panel('Không có quyền',`<p>Không hiển thị nội dung nhạy cảm trước khi kiểm quyền.</p>${btn('Xem 403','state-forbidden')}`)}</div>`;}
function preview(){const m=db.movies[selectedMovie];return head('Xem trước bản nháp','Chỉ mô phỏng metadata, không phải màn player đã tích hợp.')+panel('Nội dung mẫu',`<div style="background:#151b25;color:white;padding:30px;border-radius:12px"><span class="badge amber">PREVIEW · KHÔNG PUBLIC</span><h1 style="margin-top:20px">${E(m.title)}</h1><p>${m.year} · ${E(m.genres.join(' / '))}</p><p>${E(m.summary)}</p><div style="border:1px dashed #8390a4;padding:45px;text-align:center">Player chưa được xác minh — không phát video</div></div>`)+link('← Quay lại biên tập','movie-edit','help-link');}
function calendarView(){const days=Array.from({length:7},(_,i)=>({startsAt:`2026-11-${16+i}T00:00:00+07:00`,endsAt:`2026-11-${17+i}T00:00:00+07:00`}));return head('Lịch đặt chỗ quảng cáo','Tuần 16–22/11/2026 · UTC+7 · Dữ liệu mẫu',btn('+ Đặt chỗ','new-reservation','primary'))+panel('Độc quyền theo vị trí',`<div class="table-scroll"><div class="calendar"><div class="cal-head">Vị trí / thiết bị</div>${days.map((d,i)=>`<div class="cal-head">${i===6?'CN':'T'+(i+2)} · ${i+16}/11</div>`).join('')}${db.placements.slice(0,3).map(p=>`<div style="overflow-wrap:anywhere"><strong>${p.id}</strong></div>${days.map(day=>{const r=db.reservations.find(r=>r.status==='confirmed'&&r.placementIds.includes(p.id)&&R.overlap(day,r));const campaign=db.campaigns.find(c=>c.id===r?.campaignId);return `<div>${r?`<div class="booking ${campaign?.status==='paused'?'hold':''}">${E(campaign?.name)}<br>${campaign?.status==='paused'?'Tạm dừng · giữ chỗ':'Độc quyền'}</div>`:'<span class="muted">Chưa đặt độc quyền</span>'}</div>`;}).join('')}`).join('')}</div></div><p class="muted small" style="margin-top:12px">Lịch này chỉ thể hiện đặt chỗ độc quyền. Chia sẻ theo trọng số cấu hình ở chiến dịch, không giữ chỗ độc quyền.</p>`)+panel('Đặt chỗ đã ghi nhận',table(['Mã / chiến dịch','Vị trí','Bắt đầu','Kết thúc','Trạng thái',''],db.reservations.map(r=>[`${r.id}<div class="sub">${r.campaignId}</div>`,r.placementIds.join(', '),r.startsAt.slice(0,10),r.endsAt.slice(0,10),badge(r.status),btn('Hủy đặt chỗ','cancel-reservation','quiet',`data-id="${r.id}" ${r.status==='cancelled'?'disabled':''}`)])))+callout('Kiểm tra lại khi xác nhận','Khoảng [bắt đầu, kết thúc). Tạm dừng chiến dịch không giải phóng lịch. Backend phải khóa/xử lý transaction; kiểm tra ở trình duyệt chỉ là minh họa.','blue');}
const views={dashboard,tasks,movies,'movie-edit':movieEdit,'movie-detail':movieDetail,reviews,'review-detail':reviewDetail,publishing,providers,sources,capabilities,campaigns,'campaign-edit':campaignEdit,placements,reservations:calendarView,'reservation-new':reservationNew,'ad-rules':adRules,analytics,statements,'revenue-import':revenueImport,'statement-detail':statementDetail,reports,'report-detail':reportDetail,site,staff,roles,taxonomies,assets,episodes,sections,pages,creatives,payments,audit:auditScreen,jobs,settings,backups,components,states,preview};
const restricted={staff:['owner','admin'],roles:['owner','admin'],audit:['owner','admin'],settings:['owner','admin'],backups:['owner','admin'],jobs:['owner','admin'],statements:['owner','admin','finance'],'revenue-import':['owner','admin','finance'],'statement-detail':['owner','admin','finance'],payments:['owner','finance'],campaigns:['owner','admin','ads'],'campaign-edit':['owner','admin','ads'],reservations:['owner','admin','ads'],'reservation-new':['owner','admin','ads'],creatives:['owner','admin','ads'],placements:['owner','admin'],'ad-rules':['owner','admin'],reviews:['owner','admin'],'review-detail':['owner','admin'],publishing:['owner','admin'],providers:['owner','admin'],capabilities:['owner','admin']};
Object.assign(restricted,{movies:['owner','admin','editor'],'movie-edit':['owner','admin','editor'],'movie-detail':['owner','admin','editor'],taxonomies:['owner','admin','editor'],assets:['owner','admin','editor','ads'],episodes:['owner','admin','editor'],sources:['owner','admin','editor'],site:['owner','admin','editor'],sections:['owner','admin','editor'],pages:['owner','admin','editor'],preview:['owner','admin','editor'],reports:['owner','admin','support'],'report-detail':['owner','admin','support']});
function render(){const r=route();if(['login','mfa','recover'].includes(r)){$('#app').innerHTML=loginScreen(r);return;}const allowed=!restricted[r]||restricted[r].includes(role);const content=!allowed?stateView('forbidden'):['loading','empty','error','forbidden'].includes(viewState)?stateView(viewState):(viewState==='success'?callout('Đã lưu mẫu','Trạng thái thành công minh họa. Không có ghi dữ liệu backend.','green'):'')+(views[r]?views[r]():head('Không tìm thấy màn','Kiểm tra đường dẫn.')+link('Về tổng quan','dashboard','help-link'));$('#app').innerHTML=shell(content);}
function saveMovie(){if(!allow(['owner','admin','editor']))return false;const m=db.movies[selectedMovie];if(m.editorialState!=='draft'){showToast('Chỉ sửa bản nháp. Trả sửa hoặc tạo revision nháp trước.',true);return false;}const f=formData('#movie-form'),errors=R.validateMovie(f);if(db.movies.some((x,i)=>i!==selectedMovie&&x.slug===f.slug))errors.slug='Slug đã tồn tại.';for(const el of document.querySelectorAll('[data-error]'))el.textContent=errors[el.dataset.error]||'';if(Object.keys(errors).length){showToast('Cần sửa dữ liệu được đánh dấu.',true);return false;}Object.assign(m,{title:f.title.trim(),slug:f.slug,year:+f.year,type:f.type,genres:f.genres.split(',').map(x=>x.trim()).filter(Boolean),summary:f.summary,seoTitle:f.seoTitle,seoDescription:f.seoDescription,revision:m.revision+1});dirty=false;audit('Lưu nháp phim',m.title+' · #'+m.revision);render();showToast('Đã lưu vào bộ nhớ mẫu. Tải lại trang sẽ đặt lại.');return true;}
function bookingCandidate(){const f=formData('#reservation-form');return {campaignId:f.campaignId,placementIds:[f.placementId],startsAt:f.startsAt+':00+07:00',endsAt:f.endsAt+':00+07:00',fallback:f.fallback,reason:f.reason,status:'confirmed'};}
function checkBooking(commit){if(commit&&!allow(['owner','admin']))return;const r=bookingCandidate(),c=db.campaigns.find(c=>c.id===r.campaignId),p=db.placements.find(p=>r.placementIds.includes(p.id));let error='';if(!Number.isFinite(Date.parse(r.startsAt))||!Number.isFinite(Date.parse(r.endsAt))||Date.parse(r.startsAt)>=Date.parse(r.endsAt))error='Thời gian bắt đầu phải trước kết thúc.';else if(!r.reason.trim())error='Cần ghi chú đặt chỗ.';else if(!c||c.mode!=='exclusive'||!c.deviceClasses.includes(p.device)||Date.parse(r.startsAt)<Date.parse(c.startsAt)||Date.parse(r.endsAt)>Date.parse(c.endsAt))error='Phạm vi phải nằm trong lịch và thiết bị của chiến dịch độc quyền.';else if(R.bookingConflicts(r,db.reservations).length)error='BOOKING_CONFLICT: trùng đặt chỗ đã xác nhận.';$('#booking-result').innerHTML=callout(error?'Chưa thể xác nhận':'Không trùng lịch',error||'Kiểm tra trên dữ liệu mẫu hiện tại. Xác nhận sẽ kiểm tra lại.',error?'red':'green');if(commit&&!error){r.id='booking-demo-'+(db.reservations.length+1);db.reservations.push(r);audit('Xác nhận đặt chỗ',r.id);go('reservations');showToast('Đã xác nhận đặt chỗ mẫu.');}}
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('input',e=>{if(e.target.closest('#movie-form,#site-form,#campaign-form'))dirty=true;});
document.addEventListener('change',e=>{if(e.target.id==='demo-role'){role=e.target.value;render();}if(e.target.id==='demo-state'){viewState=e.target.value;render();}if(e.target.id==='movie-filter'){filterStatus=e.target.value;render();}if(e.target.id==='movie-search'){filterText=e.target.value;render();}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&dirty){e.preventDefault();const to=a.getAttribute('href').slice(1);modal('Bỏ thay đổi chưa lưu?',`<p>Dữ liệu đang nhập chưa được lưu vào bản mẫu.</p>`,'Bỏ thay đổi',()=>go(to));return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,m=db.movies[selectedMovie];
switch(action){
case 'close-dialog':closeDialog();break;
case 'dialog-confirm':{const callback=dialogCallback;if(!callback||callback()!==false)closeDialog();break;}
case 'menu':$('.sidebar').classList.toggle('open');break;
case 'reset':db=structuredClone(initial);selectedMovie=0;importCommitted=false;importValidated=false;dirty=false;filterText='';filterStatus='';viewState='normal';render();showToast('Đã khôi phục dữ liệu mẫu.');break;
case 'normal':viewState='normal';if(restricted[route()]&&!restricted[route()].includes(role))go('dashboard');else render();break;
case 'state-empty':case 'state-error':case 'state-loading':case 'state-forbidden':viewState=action.slice(6);render();break;
case 'select-movie':selectedMovie=db.movies.findIndex(m=>m.id===b.dataset.id);go('movie-detail');break;
case 'edit-movie':if(allow(['owner','admin','editor'])){if(m.editorialState==='approved'){m.editorialState='draft';m.revision++;audit('Tạo revision nháp',m.title);}go('movie-edit');}break;
case 'new-movie':if(allow(['owner','admin','editor'])){db.movies.push({id:'movie-demo-'+(db.movies.length+1),title:'',slug:'',year:2026,type:'movie',genres:[],summary:'',revision:1,editorialState:'draft',publicationState:'unpublished',publishedRevision:null});selectedMovie=db.movies.length-1;go('movie-edit');}break;
case 'save-movie':saveMovie();break;
case 'submit-movie':if(m.editorialState!=='draft'){showToast('Chỉ gửi duyệt từ bản nháp.',true);break;}if(saveMovie()){m.editorialState='in_review';audit('Gửi duyệt',m.title);render();showToast('Đã gửi duyệt mẫu. Chuyển sang Quản trị để duyệt.');}break;
case 'select-review':selectedMovie=db.movies.findIndex(m=>m.id===b.dataset.id);go('review-detail');break;
case 'approve-movie':case 'reject-movie':if(!allow(['owner','admin']))break;if(m.editorialState!=='in_review'){showToast('Hồ sơ không còn chờ duyệt.',true);break;}if(!$('#review-comment').value.trim()){showToast('Cần nhận xét trước khi duyệt / trả sửa.',true);break;}m.editorialState=action==='approve-movie'?'approved':'draft';audit(action==='approve-movie'?'Phê duyệt mẫu':'Trả sửa',m.title);render();showToast('Đã cập nhật hồ sơ mẫu.');break;
case 'publish-movie':case 'schedule-movie':if(!allow(['owner','admin']))break;if(m.editorialState!=='approved'){showToast('Phải duyệt đúng revision trước.',true);break;}if(m.type==='series'){showToast('Phim bộ đang chờ xác minh điều hướng tập.',true);break;}askReason('Xuất bản mô phỏng',reason=>{m.publicationState=action==='schedule-movie'?'scheduled':'live';if(action==='publish-movie')m.publishedRevision=m.revision;db.releases.unshift({id:'release-demo-'+(db.releases.length+1),title:m.title,revision:m.revision,time:action==='schedule-movie'?'17/11/2026 09:00 · mẫu':'Vừa thao tác',status:action==='schedule-movie'?'queued':'live'});audit('Release mô phỏng',reason);render();showToast('Chỉ đổi dữ liệu mẫu. Không phát hành lên website.');});break;
case 'preview-movie':go('preview');break;
case 'withdraw-movie':if(allow(['owner','admin']))askReason('Ngừng phát bản mẫu',reason=>{m.publicationState='withdrawn';audit('Ngừng phát mẫu',reason);render();});break;
case 'new-campaign':go('campaign-edit');break;
case 'save-campaign':if(!allow(['owner','admin','ads']))break;{const f=formData('#campaign-form');if(!f.name.trim()||!f.startsAt||!f.endsAt||f.startsAt>=f.endsAt){showToast('Cần tên và thời gian bắt đầu trước kết thúc.',true);break;}db.campaigns.push({id:'campaign-demo-'+(db.campaigns.length+1),name:f.name,mode:f.mode,status:'draft',deviceClasses:['desktop','tablet','mobile'],startsAt:f.startsAt+':00+07:00',endsAt:f.endsAt+':00+07:00'});audit('Tạo chiến dịch nháp mẫu',f.name);go('campaigns');}break;
case 'pause-campaign':if(allow(['owner','admin','ads']))askReason('Tạm dừng chiến dịch',reason=>{db.campaigns.find(c=>c.id===b.dataset.id).status='paused';audit('Tạm dừng — giữ đặt chỗ',reason);render();});break;
case 'new-reservation':go('reservation-new');break;
case 'check-booking':checkBooking(false);break;
case 'confirm-booking':checkBooking(true);break;
case 'cancel-reservation':if(allow(['owner','admin']))askReason('Hủy đặt chỗ và giải phóng lịch',reason=>{db.reservations.find(r=>r.id===b.dataset.id).status='cancelled';audit('Hủy đặt chỗ',reason);render();});break;
case 'kill-ads':if(allow(['owner','admin']))askReason('Tắt quảng cáo mẫu',reason=>{db.adsEnabled=false;audit('Kill switch mẫu',reason);render();showToast('Đã ghi trạng thái tắt trong mô phỏng.');});break;
case 'select-report':db.selectedReport=db.reports.findIndex(r=>r.id===b.dataset.id);go('report-detail');break;
case 'start-report':if(allow(['owner','admin','support'])){const r=db.reports[db.selectedReport||0];if(!['new','triaged'].includes(r.status)){showToast('Yêu cầu không ở trạng thái có thể bắt đầu.',true);break;}if(r.status==='new'){r.status='triaged';audit('Phân loại mẫu',r.id);}r.status='in_progress';audit('Bắt đầu xử lý',r.id);render();}break;
case 'resolve-report':if(allow(['owner','admin','support'])){const r=db.reports[db.selectedReport||0],note=$('#report-resolution').value.trim();if(r.status!=='in_progress'||!note){showToast('Cần bắt đầu xử lý và nhập kết quả trước.',true);break;}r.status='resolved';r.resolution=note;audit('Xử lý báo lỗi mẫu',note);render();}break;
case 'save-report-note':if(allow(['owner','admin','support'])){const text=$('#report-resolution').value.trim();if(!text){showToast('Nhập ghi chú trước.',true);break;}db.reports[db.selectedReport||0].note=text;audit('Ghi chú báo lỗi mẫu',text);showToast('Đã lưu ghi chú mẫu.');}break;
case 'takedown':info('Yêu cầu gỡ khẩn','Hỗ trợ gửi yêu cầu đến Chủ/Quản trị. Luồng thực tế cần bằng chứng, mức độ và xác nhận riêng trước khi gỡ.');break;
case 'save-config':if(allow(['owner','admin','editor'])){const f=formData('#site-form');if(Object.values(f).some(v=>!v.trim())){showToast('Cần điền nội dung hiển thị.',true);break;}Object.assign(db.site,f);dirty=false;audit('Lưu cấu hình nháp',f.heroTitle);render();showToast('Đã cập nhật bản nháp mẫu.');}break;
case 'validate-import':importValidated=true;$('#import-result').innerHTML=callout('File mẫu hợp lệ','2 dòng giả lập, cùng kỳ/currency. SHA-256 mẫu, chưa kiểm file đối tác thật.','green');break;
case 'commit-import':if(!allow(['owner','admin','finance']))break;if(!importValidated){showToast('Cần kiểm tra file mẫu trước.',true);break;}if(importCommitted){$('#import-result').innerHTML=callout('DUPLICATE_IMPORT','File mẫu đã được ghi nhận. Không cộng tiền lần hai.','red');break;}importCommitted=true;audit('Commit import mẫu','2 dòng giả lập');$('#import-result').innerHTML=callout('Đã ghi nhận mẫu','Không ghi vào sổ doanh thu thật. Nhấn lần nữa để thử chặn import trùng.','green');break;
case 'confirm-statement':if(!allow(['owner','admin']))break;if(db.statement.status!=='in_review'||!$('#statement-note').value.trim()){showToast('Cần kỳ chờ duyệt và giải trình trước.',true);break;}db.statement.status='confirmed';audit('Xác nhận kỳ mẫu','Số liệu giả lập');render();break;
case 'lock-statement':if(!allow(['owner','admin']))break;if(db.statement.status!=='confirmed'){showToast('Phải xác nhận kỳ trước khi khóa.',true);break;}askReason('Khóa kỳ đối soát mẫu',reason=>{db.statement.status='locked';audit('Khóa kỳ mẫu',reason);render();});break;
case 'job-error':db.jobState='failed';go('jobs');break;
case 'retry-job':if(allow(['owner','admin'])){db.jobState='succeeded';audit('Retry mô phỏng','Không có worker thật');render();showToast('Kết quả giả lập; không gọi worker.');}break;
case 'to-audit':go('audit');break;
case 'to-statement':go('statement-detail');break;
case 'to-roles':go('roles');break;
case 'login-next':go('mfa');break;
case 'login-done':go('dashboard');showToast('Đang xem phiên mẫu, không có xác thực server.');break;
case 'recover-demo':info('Phản hồi mẫu','Nếu thông tin hợp lệ, hệ thống thật sẽ gửi hướng dẫn. Prototype không gửi email.');break;
case 'asset-picker':modal('Chọn / tải ảnh',callout('Chỉ minh họa form','Không tải file hoặc dữ liệu thật.')+`<div class="fields">${field('Tên tài nguyên','assetName','poster-mau.webp')}${select('Mục đích','purpose',[['poster','Poster'],['banner','Banner'],['creative','Quảng cáo']],'poster')}${field('Văn bản thay thế','alt','Ảnh minh họa phim','text',true)}</div>`,'Đóng form');break;
case 'source-form':modal('Nguồn player mẫu',callout('Không gửi URL thật','Nguồn phải HTTPS và thuộc domain được phép.')+field('Nhãn server','label','Nguồn mẫu')+field('URL mẫu','url','https://player.example.invalid/embed/demo'),'Đóng form');break;
case 'creative-form':modal('Mẫu quảng cáo',callout('Form thiết kế','Chưa có quảng cáo thật.')+field('Tên mẫu','creativeName','Banner đồng hành')+field('URL đích đã duyệt','clickUrl','https://partner.example.invalid')+field('Kích thước CSS','size','728 × 90'),'Đóng form');break;
case 'payment-form':modal('Ghi nhận tiền nhận',callout('Chỉ là form minh họa','Không gọi ngân hàng hoặc tạo giao dịch.')+field('Mã tham chiếu duy nhất','reference','BANK-DEMO-002')+field('Số tiền VND','amount',1000000,'number')+field('Kỳ phân bổ','statement','statement-demo-001'),'Đóng form');break;
case 'invite-staff':case 'lock-staff':if(allow(['owner','admin']))info('Quản lý nhân sự mẫu','Mời/khóa/thu hồi phiên cần backend xác thực và kiểm quyền. Form prototype không gửi email hoặc khóa tài khoản thật.');break;
case 'test-provider':info('Chưa thể test đối tác','Cần embed được phép thử, domain, tài liệu và bằng chứng. Không tự chuyển trạng thái thành đã xác minh.');break;
case 'restore-info':info('Khôi phục an toàn','Yêu cầu approval và step-up; thử staging trước; chụp backup hiện trạng; kiểm dữ liệu và quyền sau khôi phục.');break;
case 'generic-form':modal(b.dataset.kind||'Biểu mẫu',callout('Phạm vi: minh họa cấu trúc','Chưa lưu backend; trường chi tiết tra contract dữ liệu.')+field('Tên / tiêu đề','name',b.dataset.kind||'Nội dung mẫu','text',true)+field('Ghi chú','note','','text',true),'Đóng form');break;
default:info('Chức năng thiết kế','Hành động này chưa được mô phỏng ghi dữ liệu. Xem contract và danh mục màn để triển khai.');
}});
$('#dialog').addEventListener('close',()=>{dialogCallback=null;lastFocus?.focus();});
window.addEventListener('hashchange',()=>{dirty=false;render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
// Read-only test snapshot, no production interface.
window.RAPDEM_TEST={snapshot:()=>structuredClone(db),role:()=>role};
render();
